<section class="comm-card"><div class="comm-head"><div><h2>Your automatic messages</h2><p class="muted">Switch them on or off and see what happened last.</p></div><input type="search" id="comm-workflow-search" placeholder="Search messages" style="max-width:230px" aria-label="Search messages"></div><div class="comm-toolbar" aria-label="Filter messages"><button class="active" type="button" data-workflow-filter="all">All</button><button type="button" data-workflow-filter="on">On</button><button type="button" data-workflow-filter="off">Off</button></div><div class="comm-scroll"><table class="comm-table" id="comm-workflow-table"><thead><tr><th>On</th><th>Name</th><th>Sends</th><th>How often</th><th>Limit per run</th><th>Next message</th><th>Last run</th><th>Remove</th></tr></thead><tbody><?php foreach($automations as $a): ?><tr data-enabled="<?= $a['enabled']?'on':'off'; ?>"><td><?= form_open('communications/automation'); ?><input type="hidden" name="id" value="<?= (int)$a['id']; ?>"><input type="hidden" name="screen" value="<?= $mobile?'mobile':'desktop'; ?>"><input name="enabled" value="1" type="checkbox" class="switch" <?= $a['enabled']?'checked':''; ?> onchange="this.form.submit()" aria-label="Switch on <?= $h($a['name']); ?>"><?= form_close(); ?></td><td class="wrap"><b><?= $h($a['name']); ?></b><br><span class="muted"><?= $h($segments[$a['segment_key']][0]??'Chosen group'); ?></span></td><td><?= $a['channel']==='email'?'Email':'Text message (SMS)'; ?></td><td><?= (int)$a['interval_days']===1?'Every day':'Every '.(int)$a['interval_days'].' days'; ?></td><td><?= number_format($a['budget_units']); ?> credits</td><td><?= $h($wat($a['next_run_at'])?:'—'); ?></td><td class="wrap <?= $a['last_error']?'error':''; ?>"><?php if($a['last_error']): ?>Needs attention: <?= $status_text($a['last_error']); ?><?php elseif($a['last_run_at']): ?>Sent <?= $h($wat($a['last_run_at'])); ?><?php else: ?>Not sent yet<?php endif; ?></td><td><?= form_open('communications/automation'); ?><input type="hidden" name="id" value="<?= (int)$a['id']; ?>"><input type="hidden" name="operation" value="archive"><input type="hidden" name="screen" value="<?= $mobile?'mobile':'desktop'; ?>"><button class="btn secondary" type="submit" data-archive-workflow="<?= $h($a['name']); ?>">Remove</button><?= form_close(); ?></td></tr><?php endforeach; ?></tbody></table></div><?php if(!$automations): ?><p class="empty">No automatic messages yet. Set one up and MartPoint will handle the follow-ups for you.</p><?php endif; ?></section>
